+/**
+ * @short An alternate calendar provider for Thai solar calendar system.
+ *
+ * This class presents an alternate calendar provider for Thai solar calendar system.
+ */
+class ThaiCalendarProvider : public AbstractCalendarProvider
+{
+    Q_OBJECT
+
+public:
+    explicit ThaiCalendarProvider(QObject *parent, CalendarSystem::System calendarSystem, const QDate &startDate, const QDate &endDate);
+    ~ThaiCalendarProvider() override;
+
+    QCalendar::YearMonthDay fromGregorian(const QDate &date) const override;
+    CalendarEvents::CalendarEventsPlugin::SubLabel subLabel(const QDate &date) const override;
+
+private:
+    const std::unique_ptr<class ThaiCalendarProviderPrivate> d;
+};
